import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as t,c as o,f as p,q as n,D as l,O as r,g as i}from"./chunks/runtime-core.esm-bundler.DabvBDJM.js";const c="/assets/mcp-2.DtLvOlNT.png",C=JSON.parse('{"title":"MCP 端到端流程：从配置到关闭","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/MCP/MCP端到端流程.md","filePath":"column/AIFuture/MCP/MCP端到端流程.md","lastUpdated":1786063092000}'),u={name:"column/AIFuture/MCP/MCP端到端流程.md"};function d(b,s,q,h,m,g){const a=t("ArticleMetadata");return p(),o("div",null,[s[0]||(s[0]=n("h1",{id:"mcp-端到端流程-从配置到关闭",tabindex:"-1"},[i("MCP 端到端流程：从配置到关闭 "),n("a",{class:"header-anchor",href:"#mcp-端到端流程-从配置到关闭","aria-label":'Permalink to "MCP 端到端流程：从配置到关闭"'},"​")],-1)),l(a),s[1]||(s[1]=r('<p><img src="'+c+`" alt="mcp-2" loading="lazy"></p><blockquote><p>本文是 MCP 的<strong>流程篇</strong>，讲&quot;怎么发生&quot;：按时间顺序，把 MCP 从打开 CodeBuddy 到关闭，完整走一遍。</p><p>以本仓库真实案例为主线：<strong>CodeBuddy + local-time MCP Server（server.js，Node.js）</strong>。</p></blockquote><p>想看&quot;是什么&quot;（角色、原语、真实报文），见 <a href="/column/AIFuture/MCP/MCP核心概念">mcp核心概念.md</a>。</p><h2 id="_0-一分钟看懂全程" tabindex="-1">0. 一分钟看懂全程 <a class="header-anchor" href="#_0-一分钟看懂全程" aria-label="Permalink to &quot;0. 一分钟看懂全程&quot;">​</a></h2><p><code>MCP</code> 的整个生命周期，其实只干一件事：<strong>让你的大模型（LLM）能调用你写的 server.js</strong>。</p><p>把整个流程压成一句话：</p><blockquote><p><strong>你配置好 server.js → 打开 CodeBuddy 时，Host 自动把 server.js 启动起来、跟它&quot;打招呼&quot;（握手）、问它有哪些工具（tools/list）→ 之后每次你提问，Host 就替大模型去调对应工具 → 拿到结果再交给大模型组织回答 → 你关闭 CodeBuddy，server.js 随之结束。</strong></p></blockquote><p>下图把整个过程画成一整条时间线（<strong>先看这张图，再往下读细节</strong>）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[你写好 server.js 并配置好]              ← 准备工作，还没人运行它</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>[打开 CodeBuddy]</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>╔══════════════ 启动阶段：Host 自动做，与你是否提问无关 ══════════════╗</span></span>
<span class="line"><span>║  ① 启动进程：node 运行 server.js（它开始监听 stdin，进入待命）      ║</span></span>
<span class="line"><span>║  ② 握手：Client ↔ server 约定协议版本、互相报能力（做一次）          ║</span></span>
<span class="line"><span>║  ③ 发现工具：Client 问 tools/list，把清单注入大模型上下文（做一次）   ║</span></span>
<span class="line"><span>╚═══════════════════════════════════════════════════════════════════╝</span></span>
<span class="line"><span>   │  （此刻一切就绪，只等你提问）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[你输入&quot;现在几点了？&quot;]                  ← 从这里起，才由&quot;提问&quot;触发</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>╔══════════════ 调用阶段：每次提问触发一次 ═══════════════════════════╗</span></span>
<span class="line"><span>║  ① 大模型 推理#1：判断&quot;该用 get_current_time&quot;（只是思考，不执行）    ║</span></span>
<span class="line"><span>║  ② Client 把意图翻译成 tools/call，经 stdin 发给 server.js         ║</span></span>
<span class="line"><span>║  ③ server.js 真正执行工具函数，经 stdout 返回结果  ← 等待发生在这    ║</span></span>
<span class="line"><span>║  ④ Client 剥壳，把结果交给大模型                                    ║</span></span>
<span class="line"><span>║  ⑤ 大模型 推理#2：组织成自然语言回答 → 显示给你                      ║</span></span>
<span class="line"><span>╚═══════════════════════════════════════════════════════════════════╝</span></span>
<span class="line"><span>   │  （server.js 一直活着，等下一次提问）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[你再提问] → 重复调用阶段 ①~⑤（不用重新握手/发现）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>[关闭 CodeBuddy]</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>server.js 子进程被终止</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><ul><li><strong>启动阶段</strong>：Host 一打开就自动完成，<strong>跟你提不提问没关系</strong>。</li><li><strong>调用阶段</strong>：<strong>每次提问</strong>触发一次。</li><li>两个阶段之间：<strong>握手和发现只做一次</strong>，之后的每次提问都复用，所以很快。</li></ul><blockquote><p>如果你刚接触 MCP，建议先读 <a href="./mcp核心概念">mcp核心概念.md</a> 里的&quot;角色&quot;（Host/Client/Server）和&quot;一张图看懂&quot;再回来，会更容易跟上。</p></blockquote><h2 id="_1-案例背景与配置" tabindex="-1">1. 案例背景与配置 <a class="header-anchor" href="#_1-案例背景与配置" aria-label="Permalink to &quot;1. 案例背景与配置&quot;">​</a></h2><h3 id="_1-1-配置" tabindex="-1">1.1 配置 <a class="header-anchor" href="#_1-1-配置" aria-label="Permalink to &quot;1.1 配置&quot;">​</a></h3><p>在 CodeBuddy 里启用这个 server，靠的是配置文件 <code>~/.codebuddy/mcp.json</code>：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;local-time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stdio&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;D:/MyProjects/local-time-mcp/server.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>简单说，这段配置告诉 CodeBuddy：<strong>&quot;local-time 这个连接器，就是用 <code>node</code> 命令去跑 <code>server.js</code>，走 stdio 通信。&quot;</strong></p><h3 id="_1-2-配置字段详解" tabindex="-1">1.2 配置字段详解 <a class="header-anchor" href="#_1-2-配置字段详解" aria-label="Permalink to &quot;1.2 配置字段详解&quot;">​</a></h3><p>配置文件告诉 Host <strong>怎么启动</strong> server 子进程。字段分两类：</p><p><strong>① MCP 官方标准字段</strong>（所有 Host 通用）：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>本例值</th></tr></thead><tbody><tr><td><code>type</code></td><td>传输方式。<code>stdio</code> = 通过标准输入输出通信，Server 作为子进程启动</td><td><code>&quot;stdio&quot;</code></td></tr><tr><td><code>command</code></td><td>要执行的<strong>程序名</strong>，Host 用它启动子进程</td><td><code>&quot;node&quot;</code></td></tr><tr><td><code>args</code></td><td>传给 <code>command</code> 的参数。<code>[server.js]</code> 即&quot;让 node 运行 server.js&quot;</td><td><code>[&quot;D:/.../server.js&quot;]</code></td></tr><tr><td><code>env</code>（可选）</td><td>给子进程设置的环境变量（如 API Key），本例没用</td><td>—</td></tr><tr><td><code>cwd</code>（可选）</td><td>子进程的工作目录，本例没用</td><td>—</td></tr></tbody></table><p>合起来，启动命令就是：<code>node D:/MyProjects/local-time-mcp/server.js</code>。</p><p><strong>② Host 扩展字段</strong>（不属于 MCP 官方规范，是 CodeBuddy 自身的）：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>示例值</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>该连接器是否禁用。<code>false</code> = 启用；<code>true</code> = 禁用（Host 不会启动它）</td><td><code>false</code></td></tr><tr><td><code>autoApprove</code></td><td><strong>自动批准</strong>的工具列表。某些工具调用需要用户确认；放进此数组的<strong>免确认自动执行</strong>。空数组 = 都不自动批准</td><td><code>[]</code></td></tr><tr><td><code>timeout</code></td><td>调用该 server 的超时时间（毫秒）。超过未响应则判定调用失败</td><td><code>60000</code>（60 秒）</td></tr></tbody></table><blockquote><p>⚠️ <code>disabled</code>、<code>autoApprove</code>、<code>timeout</code> <strong>不是 MCP 协议的一部分</strong>，是 CodeBuddy 的宿主级扩展，不同 Host 字段可能不同。MCP 官方只规定 <code>type</code>/<code>command</code>/<code>args</code>/<code>env</code> 等启动与通信字段。</p></blockquote><blockquote><p>💡 官方还允许 <code>env</code>（注入环境变量）和 <code>cwd</code>（工作目录），以及用 <code>\${VAR}</code> 语法引用环境变量。本案例未用到。</p></blockquote><h2 id="_2-启动阶段-打开-codebuddy-时自动发生" tabindex="-1">2. 启动阶段：打开 CodeBuddy 时自动发生 <a class="header-anchor" href="#_2-启动阶段-打开-codebuddy-时自动发生" aria-label="Permalink to &quot;2. 启动阶段：打开 CodeBuddy 时自动发生&quot;">​</a></h2><p>启动阶段干三件事：<strong>启动进程 → 握手 → 发现工具</strong>。全部是 Host 自动完成的，<strong>与你是否提问无关</strong>。</p><h3 id="_2-1-准备-写好-server-js-还没人运行它" tabindex="-1">2.1 准备：写好 server.js（还没人运行它） <a class="header-anchor" href="#_2-1-准备-写好-server-js-还没人运行它" aria-label="Permalink to &quot;2.1 准备：写好 server.js（还没人运行它）&quot;">​</a></h3><p>你定义了 4 个工具（<code>get_current_time</code> / <code>format_time</code> / <code>time_diff</code> / <code>list_timezones</code>），每个工具都包含：名字、描述、参数 schema（Zod）、执行回调。</p><p>此刻 server.js 只是磁盘上的一个文件，<code>node_modules</code> 里躺着它的静态依赖。<strong>还没人执行它。</strong></p><h3 id="_2-2-启动进程-node-把-server-js-拉起来" tabindex="-1">2.2 启动进程：node 把 server.js 拉起来 <a class="header-anchor" href="#_2-2-启动进程-node-把-server-js-拉起来" aria-label="Permalink to &quot;2.2 启动进程：node 把 server.js 拉起来&quot;">​</a></h3><p>双击打开 CodeBuddy，在你问任何问题之前，Host 就自动启动所有配置好的连接器：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CodeBuddy (Host) 启动</span></span>
<span class="line"><span>   │ 1. 读取 ~/.codebuddy/mcp.json</span></span>
<span class="line"><span>   │ 2. 为每个连接器准备一个 Client</span></span>
<span class="line"><span>   │ 3. 用配置启动 server 子进程</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>执行：node D:/MyProjects/local-time-mcp/server.js</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>server.js 子进程诞生，开始执行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>server.js 一启动就执行 <code>server.connect(transport)</code>：</p><ul><li><strong>监听 stdin</strong>（Node 事件循环阻塞在读取 stdin）</li><li>成为<strong>常驻待命</strong>的服务，等着收消息</li></ul><blockquote><p>白话理解：现在 Host（CodeBuddy）和 server.js 之间的&quot;电话线&quot;（stdin/stdout）已经接好了，两边都在等着通话。</p></blockquote><h3 id="_2-3-握手-双方先-对暗号" tabindex="-1">2.3 握手：双方先&quot;对暗号&quot; <a class="header-anchor" href="#_2-3-握手-双方先-对暗号" aria-label="Permalink to &quot;2.3 握手：双方先&quot;对暗号&quot;&quot;">​</a></h3><p>通信前，Client 和 Server 必须先<strong>握手（initialize）</strong>，确认&quot;咱俩说的是同一个版本、你能提供什么能力&quot;。这一步官方叫<strong>能力协商</strong>。</p><p>握手是三步（只有都完成，才允许后续请求）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Client ──stdin──▶ {&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1,&quot;method&quot;:&quot;initialize&quot;,</span></span>
<span class="line"><span>                      &quot;params&quot;:{&quot;protocolVersion&quot;:&quot;2024-11-05&quot;,&quot;capabilities&quot;:{},&quot;clientInfo&quot;:{...}}}</span></span>
<span class="line"><span>② Server ──stdout──▶ {&quot;result&quot;:{&quot;protocolVersion&quot;:&quot;2024-11-05&quot;,</span></span>
<span class="line"><span>                      &quot;capabilities&quot;:{&quot;tools&quot;:{&quot;listChanged&quot;:true}},</span></span>
<span class="line"><span>                      &quot;serverInfo&quot;:{&quot;name&quot;:&quot;local-time-server&quot;,&quot;version&quot;:&quot;1.0.4&quot;}},&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1}</span></span>
<span class="line"><span>③ Client ──stdin──▶ {&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;method&quot;:&quot;notifications/initialized&quot;}   ← 通知&quot;初始化完成&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li>① Client 报上自己想用的协议版本和能力。</li><li>② Server 回报它支持的版本（并声明自己支持 tools）。</li><li>③ Client 发一个<strong>通知</strong>确认&quot;初始化完成&quot;。<strong>这个通知没有响应</strong>。</li></ul><p>握手只在<strong>连接时做一次</strong>，不会每次提问都重来一遍。</p><h3 id="_2-4-发现工具-问-server-有哪些-货" tabindex="-1">2.4 发现工具：问 server 有哪些&quot;货&quot; <a class="header-anchor" href="#_2-4-发现工具-问-server-有哪些-货" aria-label="Permalink to &quot;2.4 发现工具：问 server 有哪些&quot;货&quot;&quot;">​</a></h3><p>Client 想知道 server 有哪些工具可用，于是请求工具列表（<code>tools/list</code>）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ──stdin──▶ {&quot;method&quot;:&quot;tools/list&quot;,&quot;params&quot;:{}}</span></span>
<span class="line"><span>Server ──stdout──▶ {&quot;result&quot;:{&quot;tools&quot;:[</span></span>
<span class="line"><span>   {&quot;name&quot;:&quot;get_current_time&quot;,&quot;description&quot;:&quot;...&quot;,&quot;inputSchema&quot;:{&quot;properties&quot;:{&quot;tz&quot;:{...}}}},</span></span>
<span class="line"><span>   {&quot;name&quot;:&quot;format_time&quot;,&quot;description&quot;:&quot;...&quot;,&quot;inputSchema&quot;:{...}},</span></span>
<span class="line"><span>   {&quot;name&quot;:&quot;time_diff&quot;,&quot;description&quot;:&quot;...&quot;,&quot;inputSchema&quot;:{...}},</span></span>
<span class="line"><span>   {&quot;name&quot;:&quot;list_timezones&quot;,&quot;description&quot;:&quot;...&quot;,&quot;inputSchema&quot;:{...}}</span></span>
<span class="line"><span>]},&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:2}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>关键点：</p><ul><li>这里的 <code>inputSchema</code> 就是你在 <code>server.tool()</code> 里写的 Zod schema，SDK 自动转成了标准 JSON Schema。</li><li>Client 拿到清单后，会把它<strong>注入大模型上下文</strong>，让大模型&quot;睁眼就知道有这 4 个工具可用、每个怎么填参数&quot;。这也是 tools/list <strong>只做一次</strong>的原因——之后每次提问都能复用这份清单。</li></ul><blockquote><p>补充：如果 server 后续<strong>动态增删了工具</strong>，会通过 <code>notifications/tools/list_changed</code> 通知 Client 刷新——但本项目工具启动时就固定了，不会用到。</p></blockquote><blockquote><p>小结：<strong>启动阶段做完，一切就绪，进入&quot;等待用户&quot;状态。</strong> 你还没开口，但背后已经全准备好了。</p></blockquote><h2 id="_3-调用阶段-每次提问触发一次" tabindex="-1">3. 调用阶段：每次提问触发一次 <a class="header-anchor" href="#_3-调用阶段-每次提问触发一次" aria-label="Permalink to &quot;3. 调用阶段：每次提问触发一次&quot;">​</a></h2><p>启动阶段是&quot;接线&quot;，调用阶段才是&quot;干活&quot;。你每次提问，都会走一遍 ①→⑤。</p><h3 id="_3-1-提问-大模型-想-一下用什么工具" tabindex="-1">3.1 提问：大模型&quot;想&quot;一下用什么工具 <a class="header-anchor" href="#_3-1-提问-大模型-想-一下用什么工具" aria-label="Permalink to &quot;3.1 提问：大模型&quot;想&quot;一下用什么工具&quot;">​</a></h3><p>你输入：&quot;现在几点了？&quot;——前面的握手和 tools/list 在启动阶段早做好了，这里只做&quot;调用&quot;这一件事。</p><p>大模型先做<strong>第一次推理</strong>（纯文本思考，不执行任何东西）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的提问 ──▶ 大模型（上下文里已有启动阶段注入的工具清单）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>大模型 推理 #1：</span></span>
<span class="line"><span>   &quot;这个问题需要查当前时间 → 用 get_current_time&quot;</span></span>
<span class="line"><span>   &quot;参数：用默认本地时区即可&quot;</span></span>
<span class="line"><span>   ──▶ 输出一个信号：&quot;调用 get_current_time&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>注意：大模型<strong>没有任何能力去运行 server.js</strong>。它只输出一个调用意图，等着 Client 去执行。</p><h3 id="_3-2-传话-client-把意图翻译成协议消息" tabindex="-1">3.2 传话：Client 把意图翻译成协议消息 <a class="header-anchor" href="#_3-2-传话-client-把意图翻译成协议消息" aria-label="Permalink to &quot;3.2 传话：Client 把意图翻译成协议消息&quot;">​</a></h3><p>Host 里的 Client 拿到大模型的意图，翻译成 JSON-RPC，往 server.js 的 stdin 写入：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ──stdin──▶ {&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:3,&quot;method&quot;:&quot;tools/call&quot;,</span></span>
<span class="line"><span>                     &quot;params&quot;:{&quot;name&quot;:&quot;get_current_time&quot;,&quot;arguments&quot;:{&quot;tz&quot;:&quot;Asia/Shanghai&quot;}}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Client 在这里只是&quot;传话&quot;，不干活。</p><h3 id="_3-3-干活-server-js-真正执行工具" tabindex="-1">3.3 干活：server.js 真正执行工具 <a class="header-anchor" href="#_3-3-干活-server-js-真正执行工具" aria-label="Permalink to &quot;3.3 干活：server.js 真正执行工具&quot;">​</a></h3><p>server.js 一直监听 stdin，收到 <code>tools/call</code> 后真正执行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收到 {&quot;method&quot;:&quot;tools/call&quot;,&quot;name&quot;:&quot;get_current_time&quot;,&quot;arguments&quot;:{&quot;tz&quot;:&quot;Asia/Shanghai&quot;}}</span></span>
<span class="line"><span>   │ 1. 解析 JSON，看到 method=tools/call</span></span>
<span class="line"><span>   │ 2. 从工具注册表（server.tool() 登记的 Map）按 name 取出回调</span></span>
<span class="line"><span>   │ 3. 把 arguments 传进去，真正执行：currentTimeInTimezone(&quot;Asia/Shanghai&quot;)</span></span>
<span class="line"><span>   │ 4. Node 运行时算出当前上海时间</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>包装成响应，写往 stdout：</span></span>
<span class="line"><span>Server ──stdout──▶ {&quot;result&quot;:{&quot;content&quot;:[{&quot;type&quot;:&quot;text&quot;,&quot;text&quot;:&quot;{...}&quot;}]},&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:3}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这里有个容易误会的地方，关于&quot;谁在等待&quot;：</p><ul><li><strong>Client 在这里阻塞等待</strong> server.js 返回。</li><li><strong>大模型并不是&quot;在等待&quot;</strong>——它的第一次推理已经结束。是 Client 拿到结果后，会发起<strong>第二次推理</strong>。</li></ul><h3 id="_3-4-回传-client-剥壳-结果交给大模型" tabindex="-1">3.4 回传：Client 剥壳，结果交给大模型 <a class="header-anchor" href="#_3-4-回传-client-剥壳-结果交给大模型" aria-label="Permalink to &quot;3.4 回传：Client 剥壳，结果交给大模型&quot;">​</a></h3><p>Client 从 stdout 读到响应后：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client 从 stdout 读到响应</span></span>
<span class="line"><span>   │ 剥壳：只提取 result.content 里的工具结果，丢掉 jsonrpc/id/result 这些协议包装</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>把&quot;原问题 + 工具结果&quot;一起再交给大模型</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>大模型 推理 #2：组织自然语言回答</span></span>
<span class="line"><span>   &quot;现在上海时间是 2026年08月06日 10:21:49，UTC+8&quot;</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>显示在 CodeBuddy 界面上</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>关键点：<strong>只有 stdout 里经 Client 剥壳的工具结果才进入大模型</strong>。stdin 是上行、stderr 是给开发者看日志的，都不进大模型。</p><h3 id="_3-5-连续对话-反复走-3-1-3-4-server-js-一直活着" tabindex="-1">3.5 连续对话：反复走 3.1~3.4，server.js 一直活着 <a class="header-anchor" href="#_3-5-连续对话-反复走-3-1-3-4-server-js-一直活着" aria-label="Permalink to &quot;3.5 连续对话：反复走 3.1~3.4，server.js 一直活着&quot;">​</a></h3><p>你继续问：&quot;那纽约现在几点？&quot;&quot;距离 2026 年底还有多少天？&quot;</p><p>每一次提问，都会重复 <strong>3.1 → 3.4</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你提问 ──▶ 大模型决策 ──▶ Client 发 tools/call ──▶ server.js 执行 ──▶ 结果回大模型 ──▶ 回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关键点：server.js <strong>不会</strong>处理完一次就退出。它一直活着、持续监听 stdin，随时接下一个请求——这就是&quot;常驻待命&quot;。</p><h3 id="_3-6-关闭-server-进程终止" tabindex="-1">3.6 关闭：server 进程终止 <a class="header-anchor" href="#_3-6-关闭-server-进程终止" aria-label="Permalink to &quot;3.6 关闭：server 进程终止&quot;">​</a></h3><p>官方把 MCP 生命周期划为三段：<strong>初始化 → 运行 → 关闭</strong>。前面 2.x 是初始化，3.1~3.5 是运行，这里就是<strong>关闭</strong>。</p><p>你关闭 CodeBuddy（Host），有两种情况：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>方式 A：Host 正常关闭（优雅）</span></span>
<span class="line"><span>   Client 取消未完成的任务（notifications/cancelled）→ 断开连接</span></span>
<span class="line"><span>   → Host 关闭所有连接器对应的子进程</span></span>
<span class="line"><span>   → server.js 子进程被终止</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方式 B：Host 被强制退出 / 崩溃</span></span>
<span class="line"><span>   → server.js 子进程作为其子进程，随之被终止</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>无论哪种方式，最后都是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server.js 子进程被终止</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>操作系统回收该进程的资源（文件句柄、内存、派生的子进程）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>关于依赖的归宿：</p><ul><li><code>node_modules</code> 里的<strong>静态依赖还在磁盘上</strong>——下次启动直接用，不重新下载（它跟着&quot;项目&quot;走，不跟&quot;进程&quot;走）。</li><li>如果 server 运行中动态创建了临时文件/连接，<strong>进程终止不会清理磁盘文件</strong>，要靠代码自己释放。</li></ul><h2 id="_4-对本项目的启发-扩展方向" tabindex="-1">4. 对本项目的启发 / 扩展方向 <a class="header-anchor" href="#_4-对本项目的启发-扩展方向" aria-label="Permalink to &quot;4. 对本项目的启发 / 扩展方向&quot;">​</a></h2><p>结合 MCP 的三个原语，本项目的扩展空间：</p><ul><li><strong>加 Resource</strong>：暴露 <code>time://now</code> 之类的只读时间资源，供 LLM 作为上下文读取。</li><li><strong>加 Prompt</strong>：预设&quot;换算时区&quot;&quot;计算节假日倒计时&quot;等模板。</li><li><strong>切传输</strong>：从 stdio 换成 Streamable HTTP，支持远程调用。</li><li><strong>发布 npm 包</strong>：<code>npx local-time-mcp-server@latest</code> 一键使用。</li></ul><h2 id="_5-官方参考" tabindex="-1">5. 官方参考 <a class="header-anchor" href="#_5-官方参考" aria-label="Permalink to &quot;5. 官方参考&quot;">​</a></h2><ul><li><strong>MCP 规范主页（含最新版本）</strong>：<a href="https://modelcontextprotocol.io/specification/2024-11-05" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2024-11-05</a></li><li><strong>基础协议（握手/生命周期/传输）</strong>：<a href="https://modelcontextprotocol.io/specification/2024-11-05/basic/lifecycle" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2024-11-05/basic/lifecycle</a></li><li><strong>服务器原语（Resources/Prompts/Tools）</strong>：<a href="https://modelcontextprotocol.io/specification/2024-11-05/server/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2024-11-05/server/</a></li><li><strong>工具规范（tools/list、tools/call）</strong>：<a href="https://modelcontextprotocol.io/specification/2024-11-05/server/tools" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2024-11-05/server/tools</a></li></ul><blockquote><p>注：MCP 仍在演进，各版本规范有差异。本文锚定 <code>2024-11-05</code> 撰写，链接也指向该版本；本项目使用的 Node SDK <code>@modelcontextprotocol/sdk</code>（1.30）在握手时会协商并实际采用更新的协议版本 <code>2025-06-18</code>。两者在本文涉及的握手流程、<code>tools/list</code>、<code>tools/call</code> 上行为一致，故不影响理解。若需对照最新规范，可将上方链接中的 <code>2024-11-05</code> 替换为 <code>2025-06-18</code>。</p></blockquote>`,88))])}const _=e(u,[["render",d]]);export{C as __pageData,_ as default};
